local function PE_Pack(...)
  return {n = select("#", ...), ...}
end

local function PE_Cmd(...)
  if type(funcLuaMenuCommand) ~= "function" then
    return false
  end
  local r = PE_Pack(pcall(funcLuaMenuCommand, ...))
  if not r[1] then
    return false
  end
  return table.unpack(r, 2, r.n)
end

-- PE ratio (0..1), exhausted; nil when there is nothing to show (no loader command, mode "log", no data)
function EVT_PE_Query(hdl)
  if EVT_PE_ABSENT or type(funcLuaCommand) ~= "function" then
    return nil
  end
  local ok, has, cur, max, ex, on, _, _, mult = pcall(funcLuaCommand, EVT_PE_CMD, hdl or 0)
  if not ok or has == nil then
    return nil                           -- no answer this frame (the mod scripts were busy on another thread): nothing shown, asked again next frame
  end
  if has ~= true or on ~= 1 or type(cur) ~= "number" or type(max) ~= "number" or max <= 0 then
    return nil
  end
  if type(mult) ~= "number" or mult ~= mult then
    mult = 1                             -- older loader: no multiplier
  end
  return EVT_PE_Rate(cur, max), ex == 1, mult
end

-- the gloss sprite (1-based index of EVT_GLOSS) at frame t of the cycle on a fill of rate (0..1), nil = in the pause
-- or nothing to shine on. The band enters fully off the fill's left end and leaves past the end of the remaining fill
-- (the part beyond is clipped by the gauge mask), so one sweep always crosses what is left of the bar.
function EVT_PE_ShineFrame(t, rate)
  local n = math.max(1, EVT_PE_SHINE_FRAMES)
  if t < 0 or t >= n or type(rate) ~= "number" or rate < EVT_PE_SHINE_MIN then
    return nil
  end
  local c0, c1 = EVT_GLOSS_C0, EVT_GLOSS_C1
  local c = c0 + (math.min(rate, 1) + (c1 - 1) - c0) * t / (n - 1 > 0 and n - 1 or 1)
  local k = math.floor((c - c0) / (c1 - c0) * (#EVT_GLOSS - 1) + 0.5)
  return math.max(0, math.min(#EVT_GLOSS - 1, k)) + 1
end

-- bar value: PE / max PE clamped to 0..1 (the gauge animation: 1 = full, 0 = empty)
function EVT_PE_Rate(cur, max)
  if type(cur) ~= "number" or type(max) ~= "number" or max <= 0 then
    return 0
  end
  local r = cur / max
  if r ~= r or r < 0 then
    return 0
  elseif r > 1 then
    return 1
  end
  return r
end

-- a layout-unit offset as a layer-position offset (the retail bubble code converts its orbit offset with the same
-- command); identity when the command does not answer
function EVT_PE_ToPos(dx, dy)
  local _, x, y = PE_Cmd(PE_CMND_LAYOUT_TO_POS, dx, dy)
  if type(x) == "number" and type(y) == "number" then
    return x, y
  end
  return dx, dy
end

-- the bubble centre, moved towards the player (ax, ay) by the length the scaled pointer lost
function EVT_PE_FacePos(x, y, ax, ay, s)
  local dx, dy = x - ax, y - ay
  local d = math.sqrt(dx * dx + dy * dy)
  local lx = EVT_PE_ToPos(EVT_PE_FACE_TAIL * (1 - s), 0)
  if d <= 0 or lx <= 0 or lx >= d then
    return x, y
  end
  local k = (d - lx) / d
  return ax + dx * k, ay + dy * k
end

-- the bar layer position: its frame centre under the bubble centre (bx, by), s = bubble scale
function EVT_PE_BarPos(bx, by, s)
  local sx, sy = EVT_PE_BAR_W / PE_FRAME_W, EVT_PE_BAR_H / PE_FRAME_H
  local ox, oy = EVT_PE_ToPos(EVT_PE_BAR_DX, -(EVT_PE_FACE_RADIUS * s + EVT_PE_BAR_GAP + EVT_PE_BAR_H / 2) + EVT_PE_BAR_DY)
  local cx, cy = EVT_PE_ToPos(PE_FRAME_CX * sx, PE_FRAME_CY * sy)
  return bx + ox - cx, by + oy - cy, sx, sy
end

local function PE_HideLayer(l)
  PE_Cmd(PE_CMND_VISIBLE, l, 0, false)
  if PE_Cmd(PE_CMND_IS_SUSPENDED, l) ~= true then
    PE_Cmd(PE_CMND_SUSPEND, l)
  end
end

local function PE_ShowLayer(l)
  if PE_Cmd(PE_CMND_IS_SUSPENDED, l) == true then
    PE_Cmd(537389555 --[[CMND_RESUME_LAYER]], l)
  end
  PE_Cmd(PE_CMND_VISIBLE, l, 0, true)
end

local function PE_HideShine()
  if EVT_PE_SHINE_SHOWN then
    EVT_PE_SHINE_SHOWN = false
    PE_HideLayer(PE_SHINE)
  end
end

local function PE_HideLabel()
  if EVT_PE_LABEL_SHOWN then
    EVT_PE_LABEL_SHOWN = false
    PE_HideLayer(PE_LABEL)
  end
end

local function PE_HideBar()
  PE_HideShine()
  PE_HideLabel()
  if EVT_PE_BAR_SHOWN then
    EVT_PE_BAR_SHOWN = false
    PE_HideLayer(PE_LAYER)
  end
end

-- a layer opened once and loaded: true = ready
local function PE_Ready(l)
  if PE_Cmd(PE_CMND_IS_OPEN, l) ~= true then
    PE_Cmd(PE_CMND_OPEN, l)
    return false, true
  end
  return PE_Cmd(PE_CMND_IS_LOADING, l) ~= true, false
end

-- the tag's layer position / scale for the bar layer at (px, py) scaled (sx, sy): the tag (frame mesh, its whole height
-- the tag picture) as tall as the bar's visible frame and level with it (same top and bottom), aspect (default 2: the
-- «PE» picture's 2:1) times as wide, its right edge EVT_PE_LABEL_GAP left of the bar's frame
function EVT_PE_LabelPos(px, py, sx, sy, aspect)
  local h = EVT_PE_LABEL_H or PE_FRAME_VIS_H * sy
  local w = (aspect or 2) * h
  local tsx, tsy = w / PE_FRAME_W, h / PE_FRAME_H
  local ox, oy = EVT_PE_ToPos(94 * sx - EVT_PE_LABEL_GAP - w / 2 + EVT_PE_LABEL_DX - PE_FRAME_CX * tsx,
    PE_FRAME_VIS_CY * sy + EVT_PE_LABEL_DY - PE_FRAME_CY * tsy)
  return px + ox, py + oy, tsx, tsy
end

-- the tag left of the bar (px, py, sx, sy = the bar layer's position and scale)
local function PE_DrawLabel(px, py, sx, sy)
  if not EVT_PE_LABEL then
    PE_HideLabel()
    return
  end
  local ready, opened = PE_Ready(PE_LABEL)
  if opened then
    pe_label_ready = false
  end
  if not ready then
    return
  end
  if not pe_label_ready then
    pe_label_ready = true
    PE_Cmd(PE_CMND_MESH_VISIBLE, PE_LABEL, PE_MESH_LABEL, false, 0)
    PE_Cmd(PE_CMND_MESH_VISIBLE, PE_LABEL, PE_MESH_EMPTY, false, 0)
    PE_Cmd(PE_CMND_MESH_VISIBLE, PE_LABEL, PE_MESH_BAR, false, 0)
    PE_Cmd(PE_CMND_SWAP_TEX, PE_LABEL, PE_ATLAS, PE_TEX_TAG, PE_TEX_FRAME, 0, 0)
  end
  local lx, ly, tsx, tsy = EVT_PE_LabelPos(px, py, sx, sy)
  PE_Cmd(PE_CMND_SCALE, PE_LABEL, tsx, tsy, 1, 0)
  PE_Cmd(PE_CMND_POS, PE_LABEL, lx, ly, 0, 0)
  if not EVT_PE_LABEL_SHOWN then
    EVT_PE_LABEL_SHOWN = true
    PE_ShowLayer(PE_LABEL)
  end
end

-- the glass shine while the multiplier is > 1: the gloss layer lies exactly on the bar (px, py, sx, sy), with the bar's
-- fill rate (the gauge mask clips it to the remaining fill) and a gloss sprite on its fill
local function PE_DrawShine(px, py, sx, sy, rate, mult)
  local on = EVT_PE_SHINE and type(mult) == "number" and mult > 1.0001
  if not on then
    pe_shine_t = 0
    PE_HideShine()
    return
  end
  local ready, opened = PE_Ready(PE_SHINE)
  if opened then
    pe_shine_ready = false
  end
  if not ready then
    return
  end
  if not pe_shine_ready then
    pe_shine_ready = true
    EVT_PE_SHINE_FRAME, EVT_PE_SHINE_RATE = nil, nil
    PE_Cmd(PE_CMND_RATE_INIT, PE_SHINE, PE_RATE_BAR, 0)
    PE_Cmd(PE_CMND_RATE_INIT, PE_SHINE, PE_RATE_RED, 0)
    PE_Cmd(PE_CMND_RATE, PE_SHINE, PE_RATE_RED, 0, 0, 0, true)   -- no red trail under the gloss
    PE_Cmd(PE_CMND_MESH_VISIBLE, PE_SHINE, PE_MESH_FRAME, false, 0)
    PE_Cmd(PE_CMND_MESH_VISIBLE, PE_SHINE, PE_MESH_LABEL, false, 0)
    PE_Cmd(PE_CMND_MESH_VISIBLE, PE_SHINE, PE_MESH_EMPTY, false, 0)
    PE_Cmd(PE_CMND_PRIM_ALPHA, PE_SHINE, 0, PE_MESH_BAR, EVT_PE_SHINE_ALPHA)
  end
  local cycle = math.max(1, EVT_PE_SHINE_FRAMES) + math.max(0, EVT_PE_SHINE_PAUSE)
  local k = EVT_PE_ShineFrame(pe_shine_t % cycle, rate)
  pe_shine_t = pe_shine_t + 1
  if k == nil then
    PE_HideShine()
    return
  end
  if EVT_PE_SHINE_FRAME ~= k then
    EVT_PE_SHINE_FRAME = k
    PE_Cmd(PE_CMND_SWAP_TEX, PE_SHINE, PE_ATLAS, EVT_GLOSS[k], PE_TEX_FILL, 0, 0)
  end
  if EVT_PE_SHINE_RATE == nil or math.abs(EVT_PE_SHINE_RATE - rate) > 0.0005 then
    EVT_PE_SHINE_RATE = rate
    PE_Cmd(PE_CMND_RATE, PE_SHINE, PE_RATE_BAR, 0, rate, 0, true)
  end
  PE_Cmd(PE_CMND_SCALE, PE_SHINE, sx, sy, 1, 0)
  PE_Cmd(PE_CMND_POS, PE_SHINE, px, py, 0, 0)
  if not EVT_PE_SHINE_SHOWN then
    EVT_PE_SHINE_SHOWN = true
    PE_ShowLayer(PE_SHINE)
  end
end

-- open the bar layer once; set it up (rates, label and red trail hidden) when it has loaded. true = ready
local function PE_OpenBar()
  if PE_Cmd(PE_CMND_IS_OPEN, PE_LAYER) ~= true then
    pe_ready = false
    PE_Cmd(PE_CMND_OPEN, PE_LAYER)
    return false
  end
  if PE_Cmd(PE_CMND_IS_LOADING, PE_LAYER) == true then
    return false
  end
  if not pe_ready then
    pe_ready = true
    EVT_PE_BAR_RATE = nil
    PE_Cmd(PE_CMND_RATE_INIT, PE_LAYER, PE_RATE_BAR, 0)
    PE_Cmd(PE_CMND_RATE_INIT, PE_LAYER, PE_RATE_RED, 0)
    PE_Cmd(PE_CMND_MESH_VISIBLE, PE_LAYER, PE_MESH_LABEL, false, 0)
    PE_Cmd(PE_CMND_MESH_VISIBLE, PE_LAYER, PE_MESH_EMPTY, false, 0)
    if type(EVT_PE_BAR_TINT) == "table" then
      PE_Cmd(PE_CMND_PRIM_COLOR, PE_LAYER, 0, PE_MESH_BAR, EVT_PE_BAR_TINT[1] or 1, EVT_PE_BAR_TINT[2] or 1, EVT_PE_BAR_TINT[3] or 1)
    end
  end
  return true
end

-- the bar follows the bubble of this frame (EVT_PE_FRAME), called after the retail bubble update and from PostStep
function EVT_PE_DrawBar()
  local fr = EVT_PE_FRAME
  if not EVT_PE_HUD or not EVT_PE_BAR or not fr.shown or fr.rate == nil or fr.x == nil then
    PE_HideBar()
    return
  end
  if not PE_OpenBar() then
    return
  end
  local px, py, sx, sy = EVT_PE_BarPos(fr.x, fr.y, EVT_PE_FACE_SCALE)
  PE_Cmd(PE_CMND_SCALE, PE_LAYER, sx, sy, 1, 0)
  PE_Cmd(PE_CMND_POS, PE_LAYER, px, py, 0, 0)
  if EVT_PE_BAR_RATE == nil or math.abs(EVT_PE_BAR_RATE - fr.rate) > 0.0005 then
    EVT_PE_BAR_RATE = fr.rate
    PE_Cmd(PE_CMND_RATE, PE_LAYER, PE_RATE_BAR, 0, fr.rate, 0, true)
    PE_Cmd(PE_CMND_RATE, PE_LAYER, PE_RATE_RED, 0, fr.rate, 0, true)
  end
  if not EVT_PE_BAR_SHOWN then
    EVT_PE_BAR_SHOWN = true
    PE_ShowLayer(PE_LAYER)
  end
  PE_DrawLabel(px, py, sx, sy)
  PE_DrawShine(px, py, sx, sy, fr.rate, fr.mult)
end

-- the controlled player's bubble (exe, every frame: handle, on screen, x, y). The retail function runs with a proxy of
-- funcLuaMenuCommand that sees the bubble's position and visibility and moves the centre for the smaller bubble;
-- every other call goes through with exactly its arguments.
local EVT_PE_prevCtrlIcon = UpdateScreenOutCtrlCharaIcon
function UpdateScreenOutCtrlCharaIcon(a1, a2, a3, a4)
  if type(EVT_PE_prevCtrlIcon) ~= "function" then
    return                               -- a twin without the include: nothing to wrap
  end
  if not EVT_PE_HUD or type(funcLuaMenuCommand) ~= "function" then
    return EVT_PE_prevCtrlIcon(a1, a2, a3, a4)
  end
  local fr = EVT_PE_FRAME
  fr.shown, fr.x, fr.y = false, nil, nil
  local s = EVT_PE_FACE_SCALE
  local real = funcLuaMenuCommand
  funcLuaMenuCommand = function(...)
    local c, layer = ...
    if layer == PE_BALLOON then
      if c == PE_CMND_POS then
        local r = {n = select("#", ...), ...}
        local x, y = r[3], r[4]
        if a2 and s ~= 1 and type(x) == "number" and type(y) == "number" and type(a3) == "number" and type(a4) == "number" then
          x, y = EVT_PE_FacePos(x, y, a3, a4, s)
          r[3], r[4] = x, y
        end
        fr.x, fr.y = x, y
        return real(table.unpack(r, 1, r.n))
      elseif c == PE_CMND_VISIBLE then
        local _, _, _, v = ...
        fr.shown = v == true
      end
    end
    return real(...)
  end
  local ok, err = pcall(EVT_PE_prevCtrlIcon, a1, a2, a3, a4)
  funcLuaMenuCommand = real
  if not ok then
    error(err, 0)
  end
  if fr.shown then
    PE_Cmd(PE_CMND_SCALE, PE_BALLOON, s, s, 1, 0)
  end
  local r, m = nil, 1
  if EVT_PE_BAR and fr.shown and type(a1) == "number" and a1 ~= 0 then
    local ex
    r, ex, m = EVT_PE_Query(a1)
  end
  fr.rate, fr.mult = r, m or 1
  EVT_PE_DrawBar()
end

-- the team dash ring: never opened (retail opens it from here); hidden if something opened it
local EVT_PE_prevDash = UpdateDashRecastMeter
function UpdateDashRecastMeter(a1, a2, a3, a4)
  if (not EVT_PE_HUD or not EVT_PE_RING_OFF) and type(EVT_PE_prevDash) == "function" then
    return EVT_PE_prevDash(a1, a2, a3, a4)
  end
  if PE_Cmd(PE_CMND_IS_OPEN, PE_RING) == true then
    PE_Cmd(PE_CMND_VISIBLE, PE_RING, 0, false)
  end
end

-- the bubble can disappear without a call of UpdateScreenOutCtrlCharaIcon (layer closed or hidden by the exe, menu
-- suspended): the bar follows its visibility every frame
local EVT_PE_prevPostStep = rawget(_ENV, "PostStep")
function PostStep(...)
  local r = {n = 0}
  if type(EVT_PE_prevPostStep) == "function" then
    r = PE_Pack(EVT_PE_prevPostStep(...))
  end
  if EVT_PE_HUD and EVT_PE_BAR_SHOWN then
    local vis = PE_Cmd(PE_CMND_IS_OPEN, PE_BALLOON) == true and PE_Cmd(PE_CMND_IS_VISIBLE, PE_BALLOON, 0) == true
    if not vis then
      EVT_PE_FRAME.shown = false
      PE_HideBar()
    end
  end
  return table.unpack(r, 1, r.n)
end
